import { Container, Nav, Navbar, NavDropdown } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import { useDispatch, useSelector } from "react-redux";
import { LinkContainer } from "react-router-bootstrap";
import { logout, setLanguage } from "../actions/userActions";

import ButtonGroup from "react-bootstrap/ButtonGroup";
import Dropdown from "react-bootstrap/Dropdown";
import DropdownButton from "react-bootstrap/DropdownButton";
import styles from "./Header.module.css";

function Header() {
  const userLogin = useSelector((state) => state.userLogin);
  const { userInfo } = userLogin;

  const dispatch = useDispatch();

  const logoutHandler = () => {
    dispatch(logout());
  };

  const { i18n } = useTranslation();
  const currentLanguage = i18n.language;

  const { t } = useTranslation();

  return (
    <header>
      <Navbar
        bg="light"
        variant="light"
        expand="lg"
        className="py-0 border-0"
        collapseOnSelect
      >
        <Container fluid>
          <LinkContainer to="/">
            <Navbar.Brand className="py-0">
              <img
                className="mr-3"
                style={{ transform: "scale(1.55)" }}
                src={`${process.env.PUBLIC_URL}/images/oblako.png`}
                width={150}
                alt="Oblako Logo"
              />
            </Navbar.Brand>
          </LinkContainer>

          <Navbar.Toggle aria-controls="basic-navbar-nav" />
          <Navbar.Collapse id="basic-navbar-nav">
            {/* TODO <SearchBox /> only appears once the user searches for something */}
            <Nav className="mr-auto">
              <NavDropdown
                title={t("header.hookah")}
                id="collasible-nav-dropdown"
              >
                <NavDropdown.Item active={false} href="#TODO">
                  {t("header.lowBudget")}
                </NavDropdown.Item>
                <NavDropdown.Item active={false} href="#TODO">
                  LUXURY
                </NavDropdown.Item>
              </NavDropdown>
              <Nav.Link href="#TODO">{t("header.tobacco")}</Nav.Link>
              <Nav.Link href="#TODO">{t("header.coals")}</Nav.Link>
              <Nav.Link href="#TODO">{t("header.temperatureControl")}</Nav.Link>
              <Nav.Link href="#TODO">{t("header.glass")}</Nav.Link>
              <Nav.Link href="#TODO">{t("header.accessories")}</Nav.Link>
              <Nav.Link href="#TODO">{t("header.offers")}</Nav.Link>
            </Nav>

            <Nav className="ml-auto">
              <DropdownButton
                as={ButtonGroup}
                variant="secondary"
                title={currentLanguage.toUpperCase()}
              >
                {["el", "en"].map((lang, i) => (
                  <Dropdown.Item
                    className={styles.dropdownItem}
                    eventKey={i}
                    onClick={() => {
                      dispatch(setLanguage(lang));
                      localStorage.setItem("userLanguage", lang);
                    }}
                    active={lang === currentLanguage ? true : undefined}
                  >
                    {lang.toUpperCase()}
                  </Dropdown.Item>
                ))}
              </DropdownButton>
              <LinkContainer to="/cart">
                <Nav.Link>
                  <i className="fas fa-shopping-cart mr-2 fa-lg"></i>
                  {t("header.cart")}
                </Nav.Link>
              </LinkContainer>
              {userInfo ? (
                <NavDropdown title={userInfo.name} id="username">
                  <LinkContainer to="/profile">
                    <NavDropdown.Item>{t("header.profile")}</NavDropdown.Item>
                  </LinkContainer>

                  <NavDropdown.Item onClick={logoutHandler}>
                    {t("header.logOut")}
                  </NavDropdown.Item>
                </NavDropdown>
              ) : (
                <LinkContainer to="/login">
                  <Nav.Link>
                    <i className="fas fa-user mr-2 fa-lg"></i>
                    {t("header.signIn")}
                  </Nav.Link>
                </LinkContainer>
              )}
              {userInfo && userInfo.isAdmin && (
                <NavDropdown title="Admin" id="adminmenue">
                  <LinkContainer to="/admin/userlist">
                    <NavDropdown.Item>{t("header.users")}</NavDropdown.Item>
                  </LinkContainer>

                  <LinkContainer to="/admin/productlist">
                    <NavDropdown.Item>{t("header.products")}</NavDropdown.Item>
                  </LinkContainer>

                  <LinkContainer to="/admin/orderlist">
                    <NavDropdown.Item>{t("header.orders")}</NavDropdown.Item>
                  </LinkContainer>
                </NavDropdown>
              )}
            </Nav>
          </Navbar.Collapse>
        </Container>
      </Navbar>
    </header>
  );
}

export default Header;
